#include <bits/stdc++.h>
using namespace std;

int main() {
    string input;
    cin >> input;
    string temp = "";
    for (size_t idx = 0; idx < input.size(); ++idx) {
        if (input[idx] == 'd' && idx + 2 < input.size() && input[idx + 1] == 'o' && input[idx + 2] == 't') {
            temp += '.';
            idx += 2;
        } else if (input[idx] == 'a' && idx + 1 < input.size() && input[idx + 1] == 't') {
            temp += '@';
            ++idx;
        } else {
            temp += input[idx];
        }
    }
    string output_str;
    if (!temp.empty()) {
        if (temp[0] == '.') output_str += "dot";
        else if (temp[0] == '@') output_str += "at";
        else output_str += temp[0];

        int at_flag = 0;
        for (size_t j = 1; j + 1 < temp.size(); ++j) {
            if (temp[j] == '@' && at_flag == 0) {
                output_str += temp[j];
                at_flag = 1;
            } else if (temp[j] == '@' && at_flag == 1) {
                output_str += "at";
            } else {
                output_str += temp[j];
            }
        }
        if (temp.back() == '.') output_str += "dot";
        else if (temp.back() == '@') output_str += "at";
        else output_str += temp.back();
    }
    cout << output_str << "\n";
}
